"""Lightweight HTTP adapters for user-hosted STT and TTS services."""import ioimport waveimport httpxfrom pydantic import SecretStrfrom .models import EngineErrorMAX_AUDIO_BYTES = 12 * 1024 * 1024def validate_wav(content: bytes) -> None:    try:        if not content or len(content) > MAX_AUDIO_BYTES:            raise ValueError        with wave.open(io.BytesIO(content), "rb") as audio:            frames = audio.getnframes()            channels = audio.getnchannels()            rate = audio.getframerate()            if (                audio.getsampwidth() != 2                or channels not in {1, 2}                or not 8000 <= rate <= 48000                or not 0 < frames <= rate * 120                or len(audio.readframes(frames)) != frames * channels * 2            ):                raise ValueError    except (wave.Error, EOFError, ValueError, OSError) as exc:        raise EngineError(            422, "Use a complete 16-bit PCM WAV, 8–48 kHz, up to 120 seconds and 12 MB."        ) from excclass SpeechClient:    def __init__(        self,        stt_base_url=None,        tts_base_url=None,        *,        stt_api_key=None,        tts_api_key=None,        timeout=60,        transport=None,    ):        self.stt_url, self.tts_url = stt_base_url, tts_base_url        self.stt_key, self.tts_key = stt_api_key, tts_api_key        self.timeout, self.transport = timeout, transport    async def call(self, url, path, key, **kwargs):        if not url:            raise EngineError(503, "The requested speech endpoint is not configured.")        secret = key.get_secret_value() if isinstance(key, SecretStr) else key        headers = {"Authorization": f"Bearer {secret}"} if secret else {}        try:            async with httpx.AsyncClient(                base_url=url.rstrip("/") + "/",                timeout=httpx.Timeout(self.timeout, connect=min(10, self.timeout)),                headers=headers,                transport=self.transport,                trust_env=False,            ) as client:                # Bound response size before buffering audio or provider error bodies.                async with client.stream("POST", path, **kwargs) as response:                    if response.status_code == 422:                        raise EngineError(422, "The speech provider rejected the input.")                    response.raise_for_status()                    parts, size = [], 0                    async for chunk in response.aiter_bytes():                        size += len(chunk)                        if size > MAX_AUDIO_BYTES:                            raise EngineError(                                503, "The speech provider response exceeded the size limit."                            )                        parts.append(chunk)                    return b"".join(parts)        except httpx.HTTPError as exc:            raise EngineError(503, "The speech provider is temporarily unavailable.") from exc    async def transcribe(self, content: bytes) -> dict:        validate_wav(content)        raw = await self.call(            self.stt_url,            "transcribe",            self.stt_key,            files={"audio": ("answer.wav", content, "audio/wav")},        )        try:            import json            value = json.loads(raw)            text = value["text"]            if not isinstance(text, str):                raise ValueError        except (ValueError, KeyError, TypeError, UnicodeDecodeError) as exc:            raise EngineError(503, "The STT provider returned an invalid transcript.") from exc        if not text.strip():            raise EngineError(422, "No speech was recognized. Record your answer again.")        if len(text) > 16000:            raise EngineError(422, "Recognized answer is too long.")        return {"text": text.strip()}    async def synthesize(self, text: str) -> bytes:        content = await self.call(self.tts_url, "synthesize", self.tts_key, json={"text": text})        try:            validate_wav(content)        except EngineError as exc:            raise EngineError(503, "The TTS provider returned invalid WAV audio.") from exc        return content